function creerEventEmitter() {
  const events = {};

  function on(event, fn) {
    if (!events[event]) events[event] = [];
    events[event].push(fn);
  }

  function off(event, fn) {
    if (!events[event]) return;
    const index = events[event].indexOf(fn);
    if (index !== -1) events[event].splice(index, 1);
  }

  function emit(event, ...args) {
    if (!events[event]) return;
    // Copy to avoid issues if listeners modify the list during emit
    events[event].forEach(fn => fn(...args));
  }

  return { on, off, emit };
}
