function creerCircuitBreaker(fn, seuil, delaiResetMs) {
  let state = 'CLOSED'; // CLOSED, OPEN, HALF_OPEN
  let failureCount = 0;
  let lastFailureTime = null;
  let halfOpenCallInProgress = false;

  return async function(...args) {
    if (state === 'OPEN') {
      // Vérifie si le délai de reset est écoulé
      if (Date.now() - lastFailureTime >= delaiResetMs) {
        state = 'HALF_OPEN';
      } else {
        throw new Error('Circuit breaker is open');
      }
    }

    if (state === 'HALF_OPEN') {
      if (halfOpenCallInProgress) {
        throw new Error('Circuit breaker is half-open; call already in progress');
      }
      halfOpenCallInProgress = true;
      try {
        const result = await fn(...args);
        // Succès : retour vers CLOSED
        state = 'CLOSED';
        failureCount = 0;
        halfOpenCallInProgress = false;
        return result;
      } catch (err) {
        // Échec : ré-ouverture
        state = 'OPEN';
        lastFailureTime = Date.now();
        halfOpenCallInProgress = false;
        throw err;
      }
    }

    // state === CLOSED
    try {
      const result = await fn(...args);
      failureCount = 0; // reset du compteur à chaque succès
      return result;
    } catch (err) {
      failureCount++;
      if (failureCount >= seuil) {
        state = 'OPEN';
        lastFailureTime = Date.now();
      }
      throw err;
    }
  };
}
```

