function creerFilePriorite() {
  const heap = []; // elements: { val, priorite }

  function enqueue(val, priorite) {
    heap.push({ val, priorite });
    let idx = heap.length - 1;
    while (idx > 0) {
      const parent = Math.floor((idx - 1) / 2);
      if (heap[parent].priorite <= heap[idx].priorite) break;
      [heap[parent], heap[idx]] = [heap[idx], heap[parent]];
      idx = parent;
    }
  }

  function dequeue() {
    if (heap.length === 0) return null;
    const min = heap[0].val;
    const last = heap.pop();
    if (heap.length > 0) {
      heap[0] = last;
      let idx = 0;
      const n = heap.length;
      while (true) {
        const left = 2 * idx + 1;
        const right = 2 * idx + 2;
        let smallest = idx;
        if (left < n && heap[left].priorite < heap[smallest].priorite) smallest = left;
        if (right < n && heap[right].priorite < heap[smallest].priorite) smallest = right;
        if (smallest === idx) break;
        [heap[idx], heap[smallest]] = [heap[smallest], heap[idx]];
        idx = smallest;
      }
    }
    return min;
  }

  function taille() {
    return heap.length;
  }

  return { enqueue, dequeue, taille };
}
