function remplirMatrice(grille, x, y, nouvelleValeur) {
    if (!grille.length || !grille[0].length) return grille;
    const rows = grille.length;
    const cols = grille[0].length;
    if (y < 0 || y >= rows || x < 0 || x >= cols) return grille;

    const target = grille[y][x];
    if (target === nouvelleValeur) return grille;

    const queue = [[y, x]];
    grille[y][x] = nouvelleValeur;
    const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];

    while (queue.length) {
        const [r, c] = queue.shift();
        for (const [dr, dc] of dirs) {
            const nr = r + dr;
            const nc = c + dc;
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grille[nr][nc] === target) {
                grille[nr][nc] = nouvelleValeur;
                queue.push([nr, nc]);
            }
